import React, { useState, useEffect } from 'react';

const SVGPlot = ({ logData, columns }) => {
	const [selectedPid, setSelectedPid] = useState('');
	const [pidOptions, setPidOptions] = useState([]);

	// Find numeric columns that can be plotted
	useEffect(() => {
		if (logData && logData.length > 0 && columns) {
			const numericCols = columns.filter(col =>
				col !== 'timestamp' && typeof logData[0][col] === 'number'
			);
			setPidOptions(numericCols);
			if (numericCols.length > 0) {
				setSelectedPid(numericCols[0]);
			}
		}
	}, [logData, columns]);

	if (!logData || logData.length < 2 || !selectedPid) {
		return <p>Not enough data to plot.</p>;
	}

	// --- SVG Plotting Logic ---
	const width = 600;
	const height = 400;
	const margin = { top: 20, right: 30, bottom: 40, left: 50 };
	const innerWidth = width - margin.left - margin.right;
	const innerHeight = height - margin.top - margin.bottom;

	const timestamps = logData.map(d => d.timestamp);
	const values = logData.map(d => d[selectedPid]);

	const minX = Math.min(...timestamps);
	const maxX = Math.max(...timestamps);
	const minY = Math.min(...values);
	const maxY = Math.max(...values);

	// Functions to scale data points to SVG coordinates
	const scaleX = (value) => margin.left + ((value - minX) / (maxX - minX)) * innerWidth;
	const scaleY = (value) => margin.top + innerHeight - ((value - minY) / (maxY - minY)) * innerHeight;

	// Create the 'd' attribute string for the SVG path
	const pathData = logData
		.map((d, i) => {
			const x = scaleX(d.timestamp);
			const y = scaleY(d[selectedPid]);
			return (i === 0 ? 'M' : 'L') + `${x},${y}`;
		})
		.join(' ');

	// Axis ticks
	const yAxisTicks = [minY, minY + (maxY-minY)/2, maxY];


	return (
		<div>
			<div style={{ marginBottom: '10px' }}>
				<label htmlFor="pid-select">Select Data to Plot: </label>
				<select id="pid-select" value={selectedPid} onChange={(e) => setSelectedPid(e.target.value)}>
					{pidOptions.map(pid => <option key={pid} value={pid}>{pid}</option>)}
				</select>
			</div>
			<svg width={width} height={height} style={{ border: '1px solid #ccc' }}>
				<g>
					{/* Y-Axis */}
					{yAxisTicks.map((tick, i) => (
						<g key={i} transform={`translate(0, ${scaleY(tick)})`}>
							<line x1={margin.left - 5} y1="0" x2={width - margin.right} y2="0" stroke="#e0e0e0" />
							<text x={margin.left - 8} y="0" dy="0.32em" textAnchor="end" fontSize="10">
								{tick.toFixed(2)}
							</text>
						</g>
					))}
					<line x1={margin.left} y1={margin.top} x2={margin.left} y2={height - margin.bottom} stroke="black" />

					{/* X-Axis */}
					<line x1={margin.left} y1={height - margin.bottom} x2={width - margin.right} y2={height - margin.bottom} stroke="black" />
					<text x={width/2} y={height-5} textAnchor="middle" fontSize="12">Time</text>

					{/* Data Path */}
					<path d={pathData} fill="none" stroke="#007bff" strokeWidth="2" />
				</g>
			</svg>
		</div>
	);
};

export default SVGPlot;
